mapper.select:
SELECT id, user_id, balance_year, total_days, used_days, adjusted_days, note
FROM leave_balances
WHERE user_id = #{userId}
  AND balance_year = #{year}

mapper.update:
UPDATE leave_balances
SET used_days = used_days + #{days}
WHERE user_id = #{userId}
  AND balance_year = #{year}

mapper.select:
SELECT id, user_id, balance_year, total_days, used_days, adjusted_days, note
FROM leave_balances
WHERE balance_year = #{year}

mapper.update:
UPDATE leave_balances
SET adjusted_days = adjusted_days + #{delta}
WHERE user_id = #{userId}
  AND balance_year = #{year}

mapper.select:
SELECT lr.id, lr.user_id, lr.type, (SELECT lt.label FROM leave_types lt WHERE lt.code = lr.type) AS type_label, lr.start_date, lr.end_date, lr.days, lr.status
FROM leave_requests lr
WHERE lr.status IN ('APPROVED', 'CANCEL_PENDING')
  AND lr.user_id = #{userId}
  AND lr.start_date <= #{workDate}
  AND lr.end_date >= #{workDate}
ORDER BY lr.id DESC
LIMIT 1

SELECT lr.id, lr.user_id, lr.type, (SELECT lt.label FROM leave_types lt WHERE lt.code = lr.type) AS type_label, lr.start_date, lr.end_date, lr.days, lr.status
FROM leave_requests lr
WHERE lr.status IN ('APPROVED', 'CANCEL_PENDING')
  AND lr.start_date <= #{toDate}
  AND lr.end_date >= #{fromDate}

SELECT id, user_id, balance_year, total_days, used_days, adjusted_days, note
FROM leave_balances
WHERE balance_year >= #{year}

SELECT code, label, day_weight, deduct_annual, evidence_required, active, sort_order
FROM leave_types
WHERE code = #{code}

mapper.update:
UPDATE leave_types
SET label = #{label}, day_weight = #{dayWeight}, deduct_annual = #{deductAnnual},
    evidence_required = #{evidenceRequired}, active = #{active}, sort_order = #{sortOrder}
WHERE code = #{code}

mapper.select:
SELECT lr.id, lr.user_id, u.name AS member_name, u.team_id, lr.type, (SELECT lt.label FROM leave_types lt WHERE lt.code = lr.type) AS type_label, lr.start_date, lr.end_date, lr.days, lr.status
FROM leave_requests lr
JOIN users u ON u.id = lr.user_id
WHERE lr.status IN ('APPROVED', 'CANCEL_PENDING')
  AND u.team_id = #{teamId}
  AND lr.start_date <= #{toDate}
  AND lr.end_date >= #{fromDate}
ORDER BY lr.start_date, lr.id

mapper.update:
UPDATE leave_requests
SET cancel_reason = #{cancelReason}
WHERE id = #{id}

UPDATE leave_requests
SET current_approval_step = #{currentApprovalStep}
WHERE id = #{id}

mapper.select:
SELECT id, work_date, start_time, end_time, note, created_by
FROM attendance_day_overrides
WHERE work_date = #{workDate}

mapper.update:
UPDATE attendance_records
SET check_out_at = #{checkOutAt}, status = #{status}
WHERE id = #{id}

UPDATE attendance_records
SET check_in_at = #{checkInAt}, check_out_at = #{checkOutAt}, status = #{status}
WHERE id = #{id}

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM attendance_corrections ac
    WHERE ac.user_id = #{userId}
      AND ac.work_date = #{workDate}
      AND ac.status = 'PENDING'
)

mapper.update:
UPDATE attendance_corrections
SET current_approval_step = #{currentApprovalStep}
WHERE id = #{id}

mapper.select:
SELECT id, trip_id, original_filename, stored_filename, content_type, file_size, uploaded_by, created_at
FROM business_trip_receipts
WHERE id = #{id}

SELECT id, trip_id, original_filename, stored_filename, content_type, file_size, uploaded_by, created_at
FROM business_trip_receipts
WHERE trip_id = #{tripId}

mapper.update:
UPDATE business_trips
SET current_approval_step = #{currentApprovalStep}
WHERE id = #{id}

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM flex_time_requests ft
    WHERE ft.user_id = #{userId}
      AND ft.status IN ('PENDING', 'APPROVED')
      AND ft.start_date <= #{endDate}
      AND ft.end_date >= #{startDate}
)

mapper.update:
UPDATE flex_time_requests
SET current_approval_step = #{currentApprovalStep}
WHERE id = #{id}

mapper.select:
SELECT id, code, label, start_time, end_time, active, sort_order
FROM shift_groups
WHERE code = #{code}

mapper.update:
UPDATE shift_groups
SET label = #{label}, start_time = #{startTime}, end_time = #{endTime},
    active = #{active}, sort_order = #{sortOrder}
WHERE id = #{id}
